import React, { useState, useEffect } from 'react';
import { Member, MembershipDue, Meeting, MemberStatus, PaymentStatus } from '../types';
import { UsersIcon, DollarSignIcon, WaterDropIcon, CalendarIcon } from './Icons';
import { GoogleGenAI } from '@google/genai';

interface DashboardPageProps {
  members: Member[];
  dues: MembershipDue[];
  meetings: Meeting[];
}

const StatCard: React.FC<{ title: string; value: string | number; icon: React.ReactNode; colorClass: string; trend?: string }> = ({ title, value, icon, colorClass, trend }) => (
  <div className="bg-white rounded-2xl p-6 shadow-sm border border-gray-100 flex flex-col justify-between hover:shadow-md transition-shadow">
    <div className="flex justify-between items-start">
      <div className={`p-3 rounded-xl ${colorClass}`}>
        {icon}
      </div>
      {trend && <span className="text-xs font-bold text-green-500 bg-green-50 px-2 py-1 rounded-lg">{trend}</span>}
    </div>
    <div className="mt-4">
      <p className="text-sm font-medium text-gray-500 uppercase tracking-wider">{title}</p>
      <p className="text-3xl font-extrabold text-gray-900 mt-1">{value}</p>
    </div>
  </div>
);

export const DashboardPage: React.FC<DashboardPageProps> = ({ members, dues, meetings }) => {
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  const activeMembers = members.filter(m => m.status === MemberStatus.Ativo).length;
  const pendingAmount = dues.filter(d => d.status !== PaymentStatus.Pago).reduce((acc, d) => acc + d.amount, 0);
  const totalConsumption = dues.filter(d => d.readingDetails).reduce((acc, d) => acc + (d.readingDetails?.consumption || 0), 0);
  const nextMeeting = meetings.length > 0 ? new Date(meetings[0].date).toLocaleDateString('pt-BR') : 'Nenhuma';

  const generateAIInsight = async () => {
    setLoadingAi(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Analise os dados desta associação rural e forneça um resumo motivacional de 2 parágrafos:
      - Localidade: ASSOCIAÇÃO COMUNITARIA UNIÃO DE SANTOS REIS
      - Total de Sócios: ${members.length}
      - Sócios Ativos: ${activeMembers}
      - Valor a Receber: R$ ${pendingAmount.toFixed(2)}
      - Consumo Total Acumulado: ${totalConsumption.toFixed(0)} m³
      Seja profissional, fale sobre sustentabilidade da água na comunidade de ASSOCIAÇÃO COMUNITARIA UNIÃO DE SANTOS REIS e saúde financeira.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt
      });
      setAiInsight(response.text);
    } catch (error) {
      setAiInsight("Mantenha o foco na gestão hídrica e no bem-estar da comunidade de ASSOCIAÇÃO COMUNITARIA UNIÃO DE SANTOS REIS!");
    } finally {
      setLoadingAi(false);
    }
  };

  useEffect(() => {
    generateAIInsight();
  }, []);

  return (
    <div className="p-8 space-y-8 animate-in fade-in duration-500">
      <div className="flex justify-between items-end">
        <div>
          <h1 className="text-4xl font-black text-gray-900 tracking-tight">Painel de Gestão</h1>
          <p className="text-gray-500 font-medium">Administração ASPRUP - ASSOCIAÇÃO COMUNITARIA UNIÃO DE SANTOS REIS</p>
        </div>
        <div className="text-right hidden md:block">
            <span className="text-xs font-bold text-gray-400 uppercase tracking-widest block">CNPJ</span>
            <span className="font-mono text-gray-700">25.215.534/0001-66</span>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
          title="Total de Sócios" 
          value={members.length} 
          icon={<UsersIcon className="w-6 h-6 text-blue-600" />} 
          colorClass="bg-blue-50 text-blue-600"
          trend="+2 este mês"
        />
        <StatCard 
          title="Consumo de Água" 
          value={`${totalConsumption.toFixed(0)} m³`} 
          icon={<WaterDropIcon className="w-6 h-6 text-blue-600" />} 
          colorClass="bg-blue-50 text-blue-600"
        />
        <StatCard 
          title="Pendente (AR)" 
          value={`R$ ${pendingAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`} 
          icon={<DollarSignIcon className="w-6 h-6 text-amber-600" />} 
          colorClass="bg-amber-50 text-amber-600"
        />
        <StatCard 
          title="Próx. Reunião" 
          value={nextMeeting} 
          icon={<CalendarIcon className="w-6 h-6 text-purple-600" />} 
          colorClass="bg-purple-50 text-purple-600"
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 bg-gradient-to-br from-slate-900 to-slate-800 rounded-3xl p-8 text-white shadow-xl relative overflow-hidden">
          <div className="relative z-10">
            <h2 className="text-2xl font-bold mb-4 flex items-center gap-2">
              <span className="bg-blue-400 w-2 h-8 rounded-full"></span>
              Visão Inteligente
            </h2>
            {loadingAi ? (
              <div className="space-y-3">
                <div className="h-4 bg-slate-700 rounded w-3/4 animate-pulse"></div>
                <div className="h-4 bg-slate-700 rounded w-1/2 animate-pulse"></div>
              </div>
            ) : (
              <p className="text-slate-50 leading-relaxed text-lg italic">
                {aiInsight || "Analizando os dados da associação para fornecer recomendações estratégicas..."}
              </p>
            )}
            <button 
                onClick={generateAIInsight}
                className="mt-6 px-4 py-2 bg-blue-500 text-white font-bold rounded-xl hover:bg-blue-400 transition-colors text-sm"
            >
                Recalcular Insights
            </button>
          </div>
          <WaterDropIcon className="absolute -bottom-10 -right-10 w-64 h-64 text-slate-700 opacity-20 rotate-12" />
        </div>

        <div className="bg-white rounded-3xl p-8 shadow-sm border border-gray-100">
            <h3 className="text-xl font-bold text-gray-900 mb-6">Status dos Sócios</h3>
            <div className="space-y-6">
                {Object.values(MemberStatus).map(status => {
                    const count = members.filter(m => m.status === status).length;
                    const pct = members.length > 0 ? (count / members.length) * 100 : 0;
                    return (
                        <div key={status}>
                            <div className="flex justify-between text-sm mb-2">
                                <span className="font-semibold text-gray-600">{status}</span>
                                <span className="font-bold text-gray-900">{count}</span>
                            </div>
                            <div className="w-full bg-gray-100 rounded-full h-3">
                                <div 
                                    className={`h-3 rounded-full transition-all duration-1000 ${
                                        status === 'Ativo' ? 'bg-blue-500' : 'bg-gray-400'
                                    }`} 
                                    style={{ width: `${pct}%` }}
                                ></div>
                            </div>
                        </div>
                    );
                })}
            </div>
        </div>
      </div>
    </div>
  );
};

