                                <div 
                                    className={`h-2 rounded-full transition-all duration-1000 ${
                                        status === 'Ativo' ? 'bg-blue-500' : 'bg-gray-400'
                                    }`} 
                                    style={{ width: `${pct}%` }}
                                ></div>
                            </div>
                        </div>
                    );
                })}
            </div>
        </div>
      </div>
    </div>
  );
};

