export const InvoiceModal: React.FC<InvoiceModalProps> = ({ isOpen, onClose, dues }) => {
  if (!isOpen || dues.length === 0) return null;

  const handlePrint = () => {
      const content = document.getElementById('printable-area');
      if (!content) return;
      const win = window.open('', '_blank');
      win?.document.write(`
        <html>
          <head>
            <title>Faturas - Administração ASPRUP</title>
            <script src="https://cdn.tailwindcss.com"></script>
            <style>
                @page { size: A4; margin: 10mm; }
                body { background-color: white; }
                @media print {
                    .no-print { display: none !important; }
                }
            </style>
          </head>
          <body>
            ${content.innerHTML}
            <script>setTimeout(() => { window.print(); window.close(); }, 800);</script>
          </body>
        </html>
      `);
      win?.document.close();
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} title={dues.length > 1 ? `Faturas (${dues.length})` : "Fatura Individual"}>
      <div className="flex justify-between mb-4 gap-2 no-print">
         <button onClick={handlePrint} className="flex-1 px-6 py-4 bg-slate-900 text-white font-black uppercase rounded-xl hover:bg-black flex items-center justify-center gap-2 shadow-xl transition-all">
            <PrinterIcon className="w-5 h-5" /> Imprimir
