        {/* Mobile Header */}
        <header className="md:hidden bg-slate-900 text-white p-4 flex justify-between items-center">
            <span className="font-bold text-sm uppercase">ASSOCIAÇÃO COMUNITARIA UNIÃO DE SANTOS REIS</span>
            <div className="flex gap-2">
                {sidebarItems.map(item => (
                    <button 
                        key={item.id} 
                        onClick={() => setActiveView(item.id as View)}
                        className={`p-1 rounded ${activeView === item.id ? 'bg-blue-700' : ''}`}
                    >
                        {React.cloneElement(item.icon as React.ReactElement, { className: 'w-5 h-5' })}
                    </button>
                ))}
