export const MembersPage: React.FC<MembersPageProps> = ({ members, onAddMember, onUpdateMember }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<MemberStatus | 'all'>('all');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingMember, setEditingMember] = useState<Member | null>(null);

  const filteredMembers = useMemo(() => {
    return members.filter(member => {
      const matchesSearch = member.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                            member.cpf.includes(searchTerm);
      const matchesStatus = statusFilter === 'all' || member.status === statusFilter;
      return matchesSearch && matchesStatus;
    });
  }, [members, searchTerm, statusFilter]);

  const handleEdit = (member: Member) => {
      setEditingMember(member);
      setIsModalOpen(true);
  };

  const handleAddNew = () => {
      setEditingMember(null);
      setIsModalOpen(true);
  };

  const handleSave = (memberData: any) => {
      if (editingMember) {
          onUpdateMember(memberData);
      } else {
          onAddMember(memberData);
      }
      setIsModalOpen(false);
      setEditingMember(null);
  };

  const exportToCSV = () => {
    const headers = ['Nome', 'CPF', 'RG', 'Endereço', 'Telefone', 'Categoria', 'Status', 'Data Filiação'];
    const rows = filteredMembers.map(m => [
        m.name,
        m.cpf,
        m.rg || '',
        m.address,
        m.phone,
        m.category,
        m.status,
        m.joinDate
    ]);

    const csvContent = [
        headers.join(','),
        ...rows.map(r => r.map(field => `"${String(field).replace(/"/g, '""')}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', `socios_buraco_do_cachorro_${new Date().toISOString().split('T')[0]}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="p-6">
       <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={editingMember ? "Editar Sócio" : "Novo Sócio"}>
        <MemberForm initialData={editingMember} onSave={handleSave} onClose={() => setIsModalOpen(false)} />
       </Modal>

      <div className="flex justify-between items-center mb-6">
        <h1 className="text-3xl font-bold text-gray-800">Sócios Cadastrados</h1>
        <div className="flex gap-2">
            <button onClick={exportToCSV} className="flex items-center gap-2 px-4 py-2 bg-blue-50 text-blue-700 border border-blue-200 rounded-lg shadow-sm hover:bg-blue-100 transition-colors">
                <DownloadIcon className="w-5 h-5" />
                Exportar Clientes
            </button>
            <button onClick={handleAddNew} className="flex items-center gap-2 px-4 py-2 bg-green-600 text-white rounded-lg shadow-sm hover:bg-green-700 transition-colors">
                <PlusIcon className="w-5 h-5" />
                Novo Sócio
            </button>
        </div>
      </div>

      <div className="bg-white p-4 rounded-lg shadow-sm mb-6">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div className="relative md:col-span-2">
            <SearchIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
            <input
              type="text"
              placeholder="Buscar por nome ou CPF..."
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
              className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-green-500 focus:border-green-500"
            />
          </div>
          <div>
            <select
              value={statusFilter}
              onChange={e => setStatusFilter(e.target.value as MemberStatus | 'all')}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-green-500 focus:border-green-500"
            >
              <option value="all">Todos os Status</option>
              {Object.values(MemberStatus).map(status => (
                <option key={status} value={status}>{status}</option>
              ))}
            </select>
          </div>
        </div>
      </div>

      <div className="bg-white rounded-lg shadow-sm overflow-x-auto">
        <table className="w-full text-sm text-left text-gray-500">
          <thead className="text-xs text-gray-700 uppercase bg-gray-50">
            <tr>
              <th scope="col" className="px-6 py-3">Nome</th>
              <th scope="col" className="px-6 py-3">CPF</th>
              <th scope="col" className="px-6 py-3">Status</th>
              <th scope="col" className="px-6 py-3 text-right">Ações</th>
            </tr>
          </thead>
          <tbody>
            {filteredMembers.map(member => (
              <tr key={member.id} className="bg-white border-b hover:bg-gray-50">
                <td className="px-6 py-4 font-medium text-gray-900 whitespace-nowrap">{member.name}</td>
                <td className="px-6 py-4">{member.cpf}</td>
                <td className="px-6 py-4">
                  <MemberStatusBadge status={member.status} />
