    [PaymentStatus.Pendente]: 'bg-blue-100 text-blue-800',
    [PaymentStatus.Atrasado]: 'bg-red-100 text-red-800',
  };
  return <span className={`${baseClasses} ${statusClasses[status]}`}>{status}</span>;
};

